-- Q3330: Interfund Transactions [medium/L1]
-- Issues: #1, #3
UPDATE questions SET
  choices = $EXPL$["Revenue recognized in the fund providing the reimbursement","Other financing sources in the fund that receives the payment","Transfers reported between the two affected governmental funds","A reduction of expenditures in the fund that is reimbursed"]$EXPL$::jsonb,
  explanation = $EXPL$Correct (D): Under GASB 34, an interfund reimbursement corrects a cost initially charged to the wrong fund. The reimbursement reduces expenditures in the fund that was incorrectly charged (general fund) and records the expenditure in the fund that should properly bear the cost (special revenue fund).
Wrong (A): Reimbursements are cost corrections, not revenue recognition events.
Wrong (B): Other financing sources apply to interfund transfers, not reimbursements.
Wrong (C): Reimbursements are distinct from transfers; they correct misallocated expenditures rather than moving resources between funds.$EXPL$
WHERE id = 3330;

-- Q3332: Interfund Transactions [easy/L2]
-- Issues: #1, #3
UPDATE questions SET
